const REFUSE: Record<Direction, string> = {
  push: "a view never sends state; ArgoniaCore accepts intents only",
  intent: "an intent is never pushed to a view",
};

// Checks one decoded message against the schema; `accept` limits the direction.
export function validate(x: unknown, accept?: Direction): Result<Message> {
  const o = members(x, "message", ["type", "v", "body"]);
  if (typeof o === "string") return { ok: false, error: o };
  if (o.type === undefined) return { ok: false, error: "message.type: missing" };
  if (typeof o.type !== "string") return { ok: false, error: "message.type: want a string" };
  if (o.v === undefined) return { ok: false, error: "message.v: missing" };
  const ve = whole(o.v, 1, MAX_SAFE, "message.v");
  if (ve !== null) return { ok: false, error: ve };
  if (o.body === undefined) return { ok: false, error: "message.body: missing" };
  const info = messageTable.find((m) => m.type === o.type);
  if (!info) return { ok: false, error: `message type '${o.type}' is not in the schema` };
  if (accept !== undefined && info.dir !== accept) return { ok: false, error: `${info.type}: ${REFUSE[info.dir]}` };
  if (o.v !== info.version) return { ok: false, error: `${info.type} version ${o.v}: this build speaks version ${info.version}` };
  const be = bodies[info.type](o.body, `${info.type} body`);
  return be === null ? { ok: true, value: o as unknown as Message } : { ok: false, error: be };
}

function parse(text: string): Result<unknown> {
  try { return { ok: true, value: JSON.parse(text) as unknown }; }
  catch (e) { return { ok: false, error: `message: JSON error: ${(e as Error).message}` }; }
}

// What a view accepts from ArgoniaCore: state pushes only.
export function decodePush(text: string): Result<PushMessage> {
  const j = parse(text);
  return (j.ok ? validate(j.value, "push") : j) as Result<PushMessage>;
}
// What ArgoniaCore accepts (the C++ twin's decode_intent); for the L3 harness and tests.
export function decodeIntent(text: string): Result<IntentMessage> {
  const j = parse(text);
  return (j.ok ? validate(j.value, "intent") : j) as Result<IntentMessage>;
}
// A view sends only what the schema holds: the intent is checked before it leaves.
export function encodeIntent(m: IntentMessage): Result<string> {
  const r = validate(m, "intent");
  return r.ok ? { ok: true, value: JSON.stringify(m) } : r;
}
// For mocks and the L3 harness, which stand in for ArgoniaCore.
export function encodePush(m: PushMessage): Result<string> {
  const r = validate(m, "push");
  return r.ok ? { ok: true, value: JSON.stringify(m) } : r;
}
